/**
 * Photography from Unsplash and one generated texture.
 *
 * Every frame below was fetched and looked at on a contact sheet before it
 * went in — a shop interior and a stock "man on a phone" were dropped, which
 * is the sort of thing that only shows up when you look.
 *
 * The light leak is generated by T1's image gateway: a real analogue leak
 * photographed against black is hard to find licensed, and this one is made
 * to the app's own amber, which is the point.
 */
const CDN = 'https://images.unsplash.com';

export function shot(id: string, w = 1200, extra = ''): string {
  return `${CDN}/${id}?auto=format&fit=crop&w=${w}&q=80${extra}`;
}

